error LSP7AmountExceedsBalance(
    uint256 balance,
    address tokenOwner,
    uint256 amount
);

/**
 * @dev reverts when `operator` of `tokenOwner` send an `amount` of tokens
 * larger than the `authorizedAmount`.
 */
error LSP7AmountExceedsAuthorizedAmount(
    address tokenOwner,
    uint256 authorizedAmount,
    address operator,
    uint256 amount
);

